#!/usr/bin/env python3
"""Embed credited source photos beside actual production captures, fully offline.
Run after capture-car-comparison.mjs and capture-track-audit.mjs against the new
production build. No network, synthetic screenshots or conceptual render assets.
"""
import base64,hashlib,html,json
from pathlib import Path
R=Path(__file__).resolve().parents[1]
read=lambda p:json.loads((R/p).read_text())
refs=read('data/photo-audit-references.json')['references'];version=read('package.json')['version']
esc=lambda s:html.escape(str(s),quote=True)
sha=lambda b:hashlib.sha256(b).hexdigest()
embed=lambda p:'data:image/jpeg;base64,'+base64.b64encode(p.read_bytes()).decode()
track_names=dict(zip(['spa','monaco','monza','silverstone','suzuka','interlagos','imola','nurburgring','montreal','hockenheim'],[t['name']for t in read('data/tracks.json')]))
car_ids={'1967':'1967-lotus','1988':'1988-mclaren','2004':'2004-ferrari','2021':'2021-red-bull','2023':'2023-red-bull'}
car_names={t['id']:t['name']+' '+t['car']for e in read('data/roster.json')['eras']for t in e['teams']}
cameras={r['id']:r['camera']for r in read('artifacts/track-captures/cameras.json')}
cards=[];captures=[]
for ref in refs:
 id=ref['id'];track=ref['category']=='track'
 capture=R/'artifacts'/('track-captures'if track else'car-captures')/((id if track else car_ids[id])+'.jpg')
 photo=R/ref['file'];assert sha(photo.read_bytes())==ref['sha256']
 name=track_names[id]if track else id+' · '+car_names[car_ids[id]]
 camera=cameras[id]if track else dict(view='Standardized 1200 × 675 showroom side view; shared race geometry/materials, not calibrated to reference camera.')
 captures.append(dict(id=id,category=ref['category'],sha256=sha(capture.read_bytes()),bytes=capture.stat().st_size,camera=camera,source='Actual production '+('race scene'if track else'showroom; same car meshes/materials as racing')))
 cards.append(f'''<article id="{id}" data-kind="{ref['category']}"><header><span>{'CIRCUIT REVIEW'if track else'CAR ERA REVIEW'}</span><h2>{esc(name)}</h2></header><div class="pair"><figure><figcaption>01 / REAL REFERENCE PHOTO</figcaption><img loading="lazy" src="{embed(photo)}" alt="Reference photograph of {esc(name)}"><p class="credit">{esc(ref['author'])} · <a href="{esc(ref['source_page'])}" target="_blank" rel="noopener">Wikimedia Commons source</a> · <a href="{esc(ref['license_url'])}" target="_blank" rel="noopener">{esc(ref['license'])}</a><br>Source date field: {esc(ref['photo_date'])}. Resized/JPEG-recompressed.</p></figure><figure><figcaption>02 / ACTUAL GAME RENDER · {version}</figcaption><img loading="lazy" src="{embed(capture)}" alt="Actual production game capture of {esc(name)}"><p class="credit">{'Production race scene, high quality, 900 × 560'if track else'Production showroom, shared race meshes/materials, 1200 × 675'}. Camera is not matched to the photograph; no numerical similarity score is claimed.</p></figure></div><div class="findings"><p><b>OBSERVED IN PHOTO</b>{esc(ref['observation'])}</p><p><b>IMPLEMENTED / RETAINED</b>{esc(ref['implemented'])}</p><p><b>STILL UNCERTAIN</b>{esc(ref['limits'])}</p></div></article>''')
style='''*{box-sizing:border-box}body{margin:0;background:#101619;color:#edf1ed;font-family:system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:32px 24px 70px}a{color:#b7dbc7;text-underline-offset:3px}nav{display:flex;justify-content:space-between;border-bottom:1px solid #38443f;padding-bottom:20px;font-size:12px;letter-spacing:.1em}h1{font-size:clamp(40px,6vw,76px);letter-spacing:-.055em;line-height:1.05;max-width:950px;margin:52px 0 24px}h1 em{font-style:normal;color:#a7ccb9}.lead{max-width:960px;color:#b5c5bd;line-height:1.8;font-size:17px}.facts{display:flex;gap:10px;flex-wrap:wrap;margin:25px 0}.facts span{border:1px solid #3d5045;padding:11px 14px;border-radius:7px;font-size:12px}.fix{background:#1b2923;border:1px solid #3e5a49;border-left:4px solid #98bda5;border-radius:8px;padding:22px 25px;line-height:1.8;max-width:1100px;font-size:14px}.fix b{display:block;letter-spacing:.12em;font-size:11px;color:#c0daca}.fix code{color:#d4e2d8;font-size:12px}.filters{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin:35px 0 24px}button{font:inherit;font-size:12px;background:#1e2a24;color:#dbe6de;border:1px solid #43574a;border-radius:30px;padding:10px 16px;cursor:pointer}button[aria-pressed=true]{background:#b5d0be;color:#14251b}.filters span{color:#9eb3a6;font-size:12px;margin-left:auto}article{border:1px solid #37483e;border-radius:12px;overflow:hidden;margin-bottom:28px;background:#17201b}header{padding:20px 25px}header span{font-size:10px;color:#a3b9ab;letter-spacing:.16em}h2{font-size:29px;letter-spacing:-.03em;margin:6px 0}.pair{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:#3c5043}figure{margin:0;min-width:0;background:#101914}figcaption{font-size:10px;letter-spacing:.1em;padding:13px 17px;color:#c9d7ce}img{display:block;width:100%;height:auto;aspect-ratio:16/10;object-fit:contain;background:#0d1410}.credit{font-size:10px;line-height:1.7;color:#a8bdb0;padding:0 17px;min-height:56px}.findings{display:grid;grid-template-columns:1fr 1fr 1fr;gap:24px;padding:22px 25px}.findings p{margin:0;color:#c2cec6;font-size:12px;line-height:1.8}.findings b{display:block;color:#a3c7af;font-size:9px;letter-spacing:.12em;margin-bottom:7px}.findings p:last-child b{color:#d3be92}footer{color:#9fb1a5;font-size:12px;line-height:1.8;padding-top:20px}.hidden{display:none!important}@media(max-width:750px){main{padding:24px 15px}nav{font-size:10px}.pair,.findings{grid-template-columns:1fr}.findings{gap:16px}.credit{min-height:0}h2{font-size:25px}h1{margin-top:35px}.filters span{width:100%;margin:5px 0}}'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APEX / HERITAGE — photo accuracy audit</title><style>{style}</style></head><body><main><nav><b>APEX / HERITAGE</b><span>PHOTO AUDIT · {version}</span></nav><h1>Photographs first.<br><em>Visible corrections.</em></h1><p class="lead">Ten circuit views. Five representative car eras. Real photographs beside actual production renders, with a record of what changed — and what the evidence does not establish.</p><div class="facts"><span>10 circuits reviewed / Spa &amp; Monaco follow-up</span><span>5 car-era proportions reviewed</span><span>15 credited source photographs</span><span>All images embedded / works offline</span></div><section class="fix"><b>TYRE WOBBLE FIXED AT THE AXLE</b>Steering and spin previously shared one XYZ Euler transform. Spinning a steered wheel tipped its axle once per revolution. The hierarchy is now <code>chassis → Y-steering hub → X-spinning tyre</code>. The hub stays aligned while the tyre rotates, including AI cars. Wheel spin and support use each actual radius, including smaller 1967 front tyres.<br><br>These are bounded, photo-guided corrections, not a full surveyed reconstruction. Source photos span different years. New Spa surfaces apply only to the latest preset; Monaco's modern hotel/tunnel is shared across all eras by request. Older surface presets remain byte-identical, including the previously requested all-era Spa/Monaco exceptions. The 2021 selection continues to use its explicitly labelled recent-surface substitute.</section><div class="filters"><button data-kind="all" aria-pressed="true">All 15 reviews</button><button data-kind="track" aria-pressed="false">10 circuits</button><button data-kind="car" aria-pressed="false">5 car eras</button><span id="count">15 reviews</span></div>{''.join(cards)}<footer><b>Scope and attribution.</b> Every reference photo retains its own linked Creative Commons license; resized photographic adaptations retain the same terms. Game screenshots are separate original rendered works. Reference photos are not game textures. No verified chassis scans or exact constructor CAD have been added. Sponsor lettering remains authored approximation, not licensed corporate vectors.<br>Photos and renders are not camera-calibrated or pixel-registered. A photograph from an older year, a restoration or an off-session view is not proof of an exact race configuration. Read the uncertainty note on each card.<br><br><a href="https://the-crab-post-office.github.io/apex-heritage/" target="_blank" rel="noopener">Play latest game ↗</a> · <a href="https://the-crab-post-office.github.io/apex-heritage/car-comparison.html" target="_blank" rel="noopener">All ten 2021 photo/game comparisons ↗</a> · <a href="https://github.com/the-crab-post-office/apex-heritage" target="_blank" rel="noopener">Source / editable audit and capture checksums ↗</a></footer></main><script>const cards=[...document.querySelectorAll('article')],buttons=[...document.querySelectorAll('button[data-kind]')];for(const button of buttons)button.onclick=()=>{{let n=0;for(const b of buttons)b.setAttribute('aria-pressed',String(b===button));for(const card of cards){{const show=button.dataset.kind==='all'||card.dataset.kind===button.dataset.kind;card.classList.toggle('hidden',!show);if(show)n++;}}document.getElementById('count').textContent=n+' reviews';}};</script></body></html>'''
(R/'web/public/photo-accuracy.html').write_text(page)
inputs=['data/car-shapes.json','data/car-layouts.json','data/corner-details.json','data/roster.json','data/car-variants.json','web/assets/liveries/manifest.json','web/wheel-motion.js','web/graphics.js','web/corners.js','web/road-surface.js','src/corner.rs','data/reference-scenes.json','web/reference-scene.js','web/venue.js']
(R/'data/photo-audit-captures.json').write_text(json.dumps(dict(version=version,inputs={p:sha((R/p).read_bytes())for p in inputs},captures=captures),indent=2)+'\n')
print('Built photo-accuracy.html:',len(page.encode()),'bytes,',len(captures),'real-photo/production-render pairs')
